from pathlib import Path
import subprocess, yaml
p=Path(".github/workflows/volume-acceptance.yml")
x=yaml.load(p.read_text(),Loader=yaml.BaseLoader)
assert {"pull_request","push","workflow_dispatch"} <= set(x["on"])
assert x["on"]["push"]["branches"] == ["main"]
assert set(x["jobs"]) == {"m6e","admission"}
for job in x["jobs"].values():
    assert job["runs-on"] == "ubuntu-24.04"
    for step in job["steps"]:
        if "run" in step:
            subprocess.run(["bash","-n"],input=step["run"],text=True,check=True)
print("YAML parsed; PR/main/dispatch, both hosted jobs and every Bash run block validated. Not a GitHub execution.")
